// D-075: one Telegram message per distinct failure per hour. Flood mode is what filled the group on 2026-09-12.
const s = $getWorkflowStaticData('global');
const e = $input.first().json;
const key = ((e.workflow && e.workflow.name) || '?') + '|' + ((e.execution && e.execution.error && e.execution.error.message) || '').slice(0, 120);
const now = Date.now(); const MUTE_MS = 60 * 60 * 1000;
s.muted = s.muted || {};
for (const k of Object.keys(s.muted)) if (now - s.muted[k].at > MUTE_MS) delete s.muted[k];
if (s.muted[key]) { s.muted[key].count += 1; return []; }
s.muted[key] = { at: now, count: 1 };
return [{ json: { ...e, dedupe_note: 'Repeats of this exact error are muted for 60 min.' } }];
